class Solution {
    public int[] divisibilityArray(String word,int m){
        int[] answer=new int[word.length()];
        long remainder=0;
        for(int i=0;i<word.length();i++){
            remainder=(remainder*10+word.charAt(i)-'0')%m;
            if(remainder==0)answer[i]=1;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun divisibilityArray(word:String,m:Int):IntArray{
        val answer=IntArray(word.length);
        var remainder=0L;
        for(i in word.indices){
            remainder=(remainder*10+(word[i]-'0'))%m;
            if(remainder==0L)answer[i]=1
        };
        return answer
    }
}

